--
-- Table structure for table `result_sheet_items`
--

DROP TABLE IF EXISTS `result_sheet_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `result_sheet_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `subject_id` bigint(20) unsigned NOT NULL,
  `subcategory_id` bigint(20) unsigned DEFAULT NULL COMMENT 'null = item sits directly under subject',
  `item_text` text NOT NULL COMMENT 'e.g. I can say my full name',
  `sort_order` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_rsi_subject_sort` (`subject_id`,`sort_order`),
  KEY `idx_rsi_subcategory` (`subcategory_id`),
  CONSTRAINT `fk_rsi_subcategory` FOREIGN KEY (`subcategory_id`) REFERENCES `result_sheet_subcategories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_rsi_subject` FOREIGN KEY (`subject_id`) REFERENCES `result_sheet_subjects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=670 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

