--
-- Table structure for table `result_sheet_ratings`
--

DROP TABLE IF EXISTS `result_sheet_ratings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `result_sheet_ratings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `template_id` bigint(20) unsigned NOT NULL,
  `item_id` bigint(20) unsigned NOT NULL,
  `student_id` bigint(20) unsigned NOT NULL,
  `session_id` bigint(20) unsigned NOT NULL,
  `term_id` bigint(20) unsigned NOT NULL,
  `rating_value` varchar(50) DEFAULT NULL COMMENT 'e.g. Good, Excellent, Not Yet',
  `rated_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rating` (`item_id`,`student_id`,`session_id`,`term_id`),
  KEY `idx_rsr_template` (`template_id`),
  KEY `idx_rsr_student_term` (`student_id`,`session_id`,`term_id`),
  KEY `idx_rsr_item` (`item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4711 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `result_sheet_ratings`
