DROP TABLE IF EXISTS `result_sheet_subcategories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `result_sheet_subcategories` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `subject_id` bigint(20) unsigned NOT NULL,
  `label` varchar(10) DEFAULT NULL COMMENT 'e.g. (a), (b)',
  `name` varchar(255) NOT NULL COMMENT 'e.g. ORAL ENGLISH',
  `sort_order` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_rssc_subject_sort` (`subject_id`,`sort_order`),
  CONSTRAINT `fk_rssc_subject` FOREIGN KEY (`subject_id`) REFERENCES `result_sheet_subjects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=283 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

