--
-- Table structure for table `result_sheet_subjects`
--

DROP TABLE IF EXISTS `result_sheet_subjects`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `result_sheet_subjects` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `template_id` bigint(20) unsigned NOT NULL,
  `course_id` bigint(20) unsigned DEFAULT NULL COMMENT 'link to courses table (nullable for custom subjects)',
  `subject_number` int(11) NOT NULL COMMENT 'display order number',
  `subject_name` varchar(255) NOT NULL COMMENT 'e.g. ENGLISH LANGUAGE',
  `sort_order` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_rss_course` (`course_id`),
  KEY `idx_rss_template_sort` (`template_id`,`sort_order`),
  CONSTRAINT `fk_rss_course` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_rss_template` FOREIGN KEY (`template_id`) REFERENCES `result_sheet_templates` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=223 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `result_sheet_subjects`
--

/*!40000 ALTER TABLE `result_sheet_subjects` DISABLE KEYS */;
