--
-- Table structure for table `result_sheet_templates`
--

DROP TABLE IF EXISTS `result_sheet_templates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `result_sheet_templates` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL COMMENT 'e.g. Nursery 2 Skill Sheet',
  `description` text DEFAULT NULL,
  `section_id` bigint(20) unsigned DEFAULT NULL COMMENT 'optional: restrict to a section',
  `term_id` bigint(20) unsigned DEFAULT NULL,
  `term_name` varchar(255) DEFAULT NULL,
  `applicable_classes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'array of school_class IDs' CHECK (json_valid(`applicable_classes`)),
  `rating_columns` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '["Not Yet","Good","V. Good","Excellent"]' CHECK (json_valid(`rating_columns`)),
  `footer_fields` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '{"footer_remark":true,"footer_class_teacher":true,...}' CHECK (json_valid(`footer_fields`)),
  `is_active` tinyint(1) DEFAULT 1,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_rst_section` (`section_id`),
  KEY `fk_rst_term` (`term_id`),
  KEY `fk_rst_created_by` (`created_by`),
  KEY `fk_rst_updated_by` (`updated_by`),
  CONSTRAINT `fk_rst_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_rst_section` FOREIGN KEY (`section_id`) REFERENCES `sections` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_rst_term` FOREIGN KEY (`term_id`) REFERENCES `terms` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_rst_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

