  KEY `user_question_orders_test_id_foreign` (`test_id`),
  KEY `user_question_orders_user_id_test_id_index` (`user_id`,`test_id`),
  CONSTRAINT `user_question_orders_test_id_foreign` FOREIGN KEY (`test_id`) REFERENCES `tests` (`id`) ON DELETE CASCADE,
  CONSTRAINT `user_question_orders_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
