DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `admission_no` varchar(255) DEFAULT NULL,
  `dob` date DEFAULT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `guardian_name` varchar(255) DEFAULT NULL,
  `guardian_phone` varchar(255) DEFAULT NULL,
  `guardian_email` varchar(255) DEFAULT NULL,
  `guardian_address` text DEFAULT NULL,
  `address` text DEFAULT NULL,
  `class_id` bigint(20) unsigned DEFAULT NULL,
  `section` int(11) DEFAULT NULL,
  `gender` varchar(255) DEFAULT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `user_type` tinyint(4) NOT NULL DEFAULT 0,
  `hostel_id` bigint(20) unsigned DEFAULT NULL,
  `is_form_teacher` tinyint(1) DEFAULT 0,
  `form_class_id` bigint(20) unsigned DEFAULT NULL,
  `other_roles` varchar(10) DEFAULT NULL,
  `added_by` bigint(20) unsigned DEFAULT NULL,
  `is_active` int(11) DEFAULT 1,
  `login_attempts` int(11) DEFAULT 3,
  `is_librarian` tinyint(1) DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`),
  UNIQUE KEY `users_admission_no_unique` (`admission_no`),
  KEY `users_added_by_foreign` (`added_by`),
  KEY `users_class_id_foreign` (`class_id`),
  KEY `users_form_class_id_foreign` (`form_class_id`),
  KEY `users_hostel_id_foreign` (`hostel_id`),
  CONSTRAINT `users_added_by_foreign` FOREIGN KEY (`added_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_class_id_foreign` FOREIGN KEY (`class_id`) REFERENCES `school_classes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_form_class_id_foreign` FOREIGN KEY (`form_class_id`) REFERENCES `school_classes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_hostel_id_foreign` FOREIGN KEY (`hostel_id`) REFERENCES `hostels` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=983 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
